        self.stop_ns=stop_ns;self.io=io;self.clock=clock;self.owned={};self.rows={}
        self.events=[];self.failures=[];self.close_attempts=[];self.open_complete=False
        self.closed=False;self.final_checked=False;self.bodies={}
